package com.bananalab.lite;
import java.util.*;import org.json.*;
public class Stage34Check{
 static void check(boolean b,String why){if(!b)throw new AssertionError(why);}
 public static void main(String[] args)throws Exception{Semilla m=SemillaCheck.load(args[0]+"/assets/language");CreatorPersistenceCheck.Fake c=new CreatorPersistenceCheck.Fake();List<String[]> history=new ArrayList<>();
  BananaEngine.Result design=BananaEngine.run(c,"crea a Tony una banana detective con sobretodo",history,"",true,m);check(design.scene!=null&&design.changed&&!design.draft,"unified design");JSONArray rows=BananaConversation.append(new JSONArray(),"Banana",design.text,design.scene,false);BananaConversation.save(c,rows,design.topic);String first=BananaConversation.snapshot(rows.getJSONObject(0)).json().toString();
  BananaEngine.Result action=BananaEngine.run(c,"Tony baila mientras entra el pepino y despues el pepino le entrega una caja a Tony y ambos se sorprenden",history,"",true,m);check(action.scene.cast.size()==2&&action.scene.actions.size()==7,"unified actions");check(BananaConversation.snapshot(rows.getJSONObject(0)).json().toString().equals(first),"immutable earlier result");
  SceneDraft expected=action.scene.copy(),changed=expected.copy();SceneDraft selected=expected.copy();selected.focused="banana";check(BananaProject.same(selected,expected),"selection does not create a different result version");changed.get("banana").look="azul lentes";BananaProject.edit(c,expected,changed);check(BananaProject.current(c).get("banana").look.equals("azul lentes"),"inline edit uses same project");boolean stale=false;try{BananaProject.edit(c,expected,expected);}catch(Exception e){stale=true;}check(stale,"stale edit rejected");
  BananaEngine.Result undo=BananaEngine.run(c,"deshacer",history,"",true,m);check(undo.changed&&undo.scene.get("banana").look.contains("sobretodo"),"same undo history");
  BananaEngine.run(c,"recorda que Tony vive en el bosque",history,"",true,m);check(BananaEngine.run(c,"mis recuerdos",history,"",true,m).text.contains("bosque"),"shared project memory");
  BananaEngine.Result draft=BananaEngine.run(c,"agrega un gato sin dibujar",history,"",true,m);check(draft.draft&&draft.scene.cast.size()==3&&SceneStore.load(c).cast.size()==2,"draft isolation");SceneDraft pending=BananaProject.current(c),edited=pending.copy();edited.get("gato").view="back";BananaProject.edit(c,pending,edited);check(BananaProject.isDraft(c)&&SceneStore.load(c).get("gato")==null,"inline draft edits stay pending");boolean blocked=false;try{BananaProject.restore(c,design.scene);}catch(Exception e){blocked=true;}check(blocked,"historical restore cannot discard pending draft");
  BananaEngine.Result publish=BananaEngine.run(c,"publica el borrador",history,"",true,m);check(!publish.draft&&publish.scene.get("gato").view.equals("back"),"publish shared draft");
  rows=BananaConversation.append(rows,"Vos","hola",null,false);rows=BananaConversation.append(rows,"Banana","hola",publish.scene,false);BananaConversation.save(c,rows,"");check(BananaConversation.load(c).length()==3&&BananaConversation.context(rows).size()==1,"history migration and context");
  JSONObject export=BananaExporter.request(c,"mp4",publish.scene);BananaProject.restore(c,design.scene);check(export.getJSONObject("scene").getJSONArray("cast").length()==3&&BananaProject.current(c).cast.size()==1,"export captures original snapshot");
  c.fail=true;boolean failed=false;try{BananaConversation.save(c,new JSONArray(),"");}catch(Exception e){failed=true;}check(failed&&BananaConversation.load(c).length()==3,"history failure does not erase saved messages");
  DialogueMemory.reply(c,"me llamo tiziano");DialogueMemory.resetConversation(c);check(DialogueMemory.reply(c,"como me llamo").contains("tiziano"),"clearing conversation retains identity memory");
  JSONArray labels=BananaConversation.append(new JSONArray(),"Vos","hola",null,false);labels=BananaConversation.append(labels,"Banana","[Texto experimental · 3 tokens]\nhola",null,false);check(BananaConversation.context(labels).get(0)[1].equals("hola"),"internal result label is not model context");
  System.out.println("PASS unified engine, immutable cards, shared editing/undo/memory, draft isolation/publication, stale edits, export snapshots and old history compatibility");
 }
}
